template<>struct Wire<NE_POLICY> {static Json Encode(const NE_POLICY& v){Json j=Json::object();j["version"]=EncodeWire(v.version);j["size"]=EncodeWire(v.size);j["process_id"]=EncodeWire(v.process_id);j["remote_ipv4"]=EncodeWire(v.remote_ipv4);j["remote_port"]=EncodeWire(v.remote_port);j["drop_every"]=EncodeWire(v.drop_every);j["delay_ms"]=EncodeWire(v.delay_ms);j["jitter_ms"]=EncodeWire(v.jitter_ms);j["reserved"]=EncodeWire(v.reserved);return j;}static void Decode(const Json& j,NE_POLICY& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="size")DecodeWire(it.value(),v.size);else if(it.key()=="process_id")DecodeWire(it.value(),v.process_id);else if(it.key()=="remote_ipv4")DecodeWire(it.value(),v.remote_ipv4);else if(it.key()=="remote_port")DecodeWire(it.value(),v.remote_port);else if(it.key()=="drop_every")DecodeWire(it.value(),v.drop_every);else if(it.key()=="delay_ms")DecodeWire(it.value(),v.delay_ms);else if(it.key()=="jitter_ms")DecodeWire(it.value(),v.jitter_ms);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
