template<>struct Wire<TITAN_AUTHORIZATION_CHALLENGE> {static Json Encode(const TITAN_AUTHORIZATION_CHALLENGE& v){Json j=Json::object();j["magic"]=EncodeWire(v.magic);j["version"]=EncodeWire(v.version);j["product"]=EncodeWire(v.product);j["duration_seconds"]=EncodeWire(v.duration_seconds);j["nonce"]=EncodeWire(v.nonce);return j;}static void Decode(const Json& j,TITAN_AUTHORIZATION_CHALLENGE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="magic")DecodeWire(it.value(),v.magic);else if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="product")DecodeWire(it.value(),v.product);else if(it.key()=="duration_seconds")DecodeWire(it.value(),v.duration_seconds);else if(it.key()=="nonce")DecodeWire(it.value(),v.nonce);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
